# Sanitized snapshot for reading. Machine-specific and not runnable as is. Generated from tools/finalrun.ps1.
# Final normal cycle: no test plugins, test mode off. Join, smoke, Log Out, rejoin, Log Out, quit, then log capture and verification.
# -Stage setup installs and joins; -Stage play does the rest. Kept apart so each fits one foreground call.
param([ValidateSet('setup','play','all')][string]$Stage = 'all', [string]$OutDir = 'evidence\final')
$w = 'S:\Documents\ChatGPT\PoVPlusPlus'; $p = "$env:APPDATA\com.kesomannen.gale\valheim\profiles\PoVPlus"; $b = "$p\BepInEx"; $i = '<steam-library>\.bakaloader-instances\Path Of Valheiman Plus'; $req = "$env:USERPROFILE\AppData\LocalLow\IronGate\Valheim\servers\Path Of Valheiman Plus\ServerManager\required"; $log = "$b\LogOutput.log"; $e = "$w\$OutDir"; New-Item -ItemType Directory -Force $e | Out-Null
if ($Stage -ne 'play') { & "$w\tools\compatsetup.ps1" -NoTest -Admin | Out-Null }; if ($Stage -eq 'setup') { return }
. "$w\tools\ui.ps1"; FocusGame; Key enter 200; Start-Sleep 25; Key tab; Start-Sleep 2; Shot "$e\inventory.png"; Key tab; Start-Sleep 1; [Ui]::Press(0x32, 90); Start-Sleep 2.5; Shot "$e\map.png"; [Ui]::Press(0x32, 90); Start-Sleep 1.5
function Con($c) { FocusGame; Key f5; Start-Sleep 1; [Ui]::Press(0x0E, 60); Start-Sleep .2; TypeText $c; Start-Sleep .4; Key enter 240; Start-Sleep 1; Key f5; Start-Sleep 1 }
function Db { Get-ChildItem "$w\.sandbox\srv-saves\worlds_local\PovSrvTest" -Filter '_main*.db2' | Sort-Object LastWriteTime | Select-Object -Last 1 }
Con 'goto -58 343'; Start-Sleep 10; Con 'cm:spawn Greyling toxicAura 2'; Start-Sleep 12; Shot "$e\aura.png"; Con 'killall'; Start-Sleep 3
$db0 = Db; Con 'save'; Start-Sleep 15; $db1 = Db; $saveLine = "save: newest world file $($db0.Name) -> $($db1.Name), new file $($db0.Name -ne $db1.Name), age $([int]((Get-Date) - $db1.LastWriteTime).TotalSeconds)s"
function Out1 { $n0 = (Get-Content $log).Count; foreach ($y in 984, 978, 992) { Key esc; Start-Sleep 1.5; Click 220 $y; Start-Sleep 2; Click 612 772; Start-Sleep 6; if (Get-Content $log | Select-Object -Skip $n0 | Select-String 'Local player destroyed') { return $true }; Key esc; Start-Sleep 1; Key esc; Start-Sleep 1 }; $false }
$o1 = Out1; Start-Sleep 18; $mark = (Get-Content $log).Count; FocusGame; Click 1280 830; Start-Sleep 3; Click 1280 1044; $t0 = Get-Date; while (((Get-Date) - $t0).TotalSeconds -lt 170) { [Threading.Thread]::Sleep(4000); if (Get-Content $log | Select-Object -Skip $mark | Select-String -SimpleMatch 'Lobby To World profile completed') { break } }; $rj = [bool](Get-Content $log | Select-Object -Skip $mark | Select-String -SimpleMatch 'Lobby To World profile completed'); Start-Sleep 14; FocusGame; Key enter 200; Start-Sleep 3; Shot "$e\rejoin.png"; $o2 = Out1; Start-Sleep 15
$g = Get-Process valheim -EA 0; if ($g) { $g.CloseMainWindow() | Out-Null; if (-not $g.WaitForExit(45000)) { Stop-Process -Id $g.Id -Force }; Start-Sleep 4 }
$s = Get-Process valheim_server -EA 0; if ($s) { $s.CloseMainWindow() | Out-Null; if (-not $s.WaitForExit(70000)) { Stop-Process -Id $s.Id -Force } }; Start-Sleep 3
foreach ($x in @(@($log, 'client-LogOutput.log'), @("$i\BepInEx\LogOutput.log", 'server-LogOutput.log'))) { ([IO.File]::ReadAllText($x[0]) -replace '<user>', '<user>' -replace '7656\d{13}', '<steamid>') | Set-Content "$e\$($x[1])" -Encoding utf8NoBOM }
function Map($d) { $h = @{}; Get-ChildItem $d -Recurse -Filter *.dll | ForEach-Object { $h[$_.FullName.Substring($d.Length)] = (Get-FileHash $_.FullName).Hash }; $h }
$c = Map "$b\plugins"; $sv = Map "$i\BepInEx\plugins"; $r = Map $req
$o = @("logout1 $o1, rejoin $rj, logout2 $o2", $saveLine); $o += (Select-String -Path "$e\client-LogOutput.log" -Pattern 'Chainloader startup complete').Line; $o += (Select-String -Path "$e\server-LogOutput.log" -Pattern 'Chainloader startup complete').Line
foreach ($pt in 'Exception', 'Gave up building sleep HUD', 'Feed Barrel dispensing stopped', 'final character save', 'transpiler bypassed') { $o += "$pt : client $(@(Select-String -Path "$e\client-LogOutput.log" -SimpleMatch $pt).Count), server $(@(Select-String -Path "$e\server-LogOutput.log" -SimpleMatch $pt).Count)" }
$o += "HarmonyX: client $(@(Select-String -Path "$e\client-LogOutput.log" -Pattern '^\[Warning:\s*HarmonyX\]').Count), server $(@(Select-String -Path "$e\server-LogOutput.log" -Pattern '^\[Warning:\s*HarmonyX\]').Count)"
$o += "client $($c.Count) server $($sv.Count) required $($r.Count); diffs client/server $(@(($c.Keys + $sv.Keys | Sort-Object -Unique) | Where-Object { $c[$_] -cne $sv[$_] -and $_ -notmatch 'Baka' }).Count), client/required $(@(($c.Keys + $r.Keys | Sort-Object -Unique) | Where-Object { $c[$_] -cne $r[$_] }).Count)"
$o += "old/test files: $(@(foreach ($d in "$b\plugins", "$i\BepInEx\plugins", $req) { Get-ChildItem $d -Recurse -File | Where-Object { $_.Name -match 'ClientProbe|IdsProbe|CallerTrace|WorldCensus|FeedBarrelStackCompat|HealthRegenCompat|ItemDataStackCompat|QuietLookups|RodBagInputBridge|BurstMultiShot|BetterSleepHudBridge|PlanBuild|UsefulTankards.Bridge' } }).Count)"
$o += (Select-String -Path "$i\BepInEx\config\vapok.mods.BetterSleepBruh.cfg" -Pattern '^(Enable Testing Mode|Fake Total Players|Simulate Players In Bed) =').Line
$o += (Select-String -Path "$i\BepInEx\config\*FineDining*" -Pattern 'Pause Spoilage In Winter =').Line; $o += "PoVPlus.Compat deployed $((Get-FileHash "$b\plugins\PoVPlus_Compat\PoVPlus.Compat.dll").Hash)"; $o += "required $((Get-FileHash (Get-ChildItem $req -Recurse -Filter PoVPlus.Compat.dll).FullName).Hash)"
$o | ForEach-Object { "$_".Substring(0, [Math]::Min(125, "$_".Length)) } | Set-Content "$e\final.txt"
Add-Content "$e\final.txt" DONE
